const visual = {
  prepare: function (input) {
    return [
      {kind:'text', payload:'G'},
      {kind:'text', payload:'N'},
      {kind:'text', payload:'f'},
      {kind:'text', payload:'30°'}
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var bw = 640, bh = 420;
    var s = Math.min(W / bw, H / bh);
    var ox = (W - bw * s) / 2;
    var oy = (H - bh * s) / 2;
    function X(x) { return ox + x * s; }
    function Y(y) { return oy + y * s; }
    function lineCmds(a, b) {
      return [['M', X(a[0]), Y(a[1])], ['L', X(b[0]), Y(b[1])]];
    }
    function polyCmds(pts) {
      var c = [];
      for (var i = 0; i < pts.length; i++) {
        c.push([i === 0 ? 'M' : 'L', X(pts[i][0]), Y(pts[i][1])]);
      }
      return c;
    }
    function arcSegCmds(pts) {
      var c = [];
      for (var i = 0; i < pts.length - 1; i++) {
        c.push(['M', X(pts[i][0]), Y(pts[i][1])]);
        c.push(['L', X(pts[i + 1][0]), Y(pts[i + 1][1])]);
      }
      return c;
    }
    function arrowCmds(a, b) {
      var c = [];
      c.push(['M', X(a[0]), Y(a[1])]);
      c.push(['L', X(b[0]), Y(b[1])]);
      var ang = Math.atan2(b[1] - a[1], b[0] - a[0]);
      var hl = 14, ha = Math.PI / 6;
      var h1 = [b[0] - hl * Math.cos(ang - ha), b[1] - hl * Math.sin(ang - ha)];
      var h2 = [b[0] - hl * Math.cos(ang + ha), b[1] - hl * Math.sin(ang + ha)];
      c.push(['M', X(h1[0]), Y(h1[1])]);
      c.push(['L', X(b[0]), Y(b[1])]);
      c.push(['L', X(h2[0]), Y(h2[1])]);
      return c;
    }
    var A = [90, 330];
    var B = [470, 330];
    var C = [470, 330 - 380 * Math.tan(Math.PI / 6)];
    var u = [Math.cos(Math.PI / 6), -Math.sin(Math.PI / 6)];
    var n = [-Math.sin(Math.PI / 6), -Math.cos(Math.PI / 6)];
    var d = 210, half = 35;
    var c = [A[0] + d * u[0] + half * n[0], A[1] + d * u[1] + half * n[1]];
    var v1 = [c[0] + half * u[0] + half * n[0], c[1] + half * u[1] + half * n[1]];
    var v2 = [c[0] + half * u[0] - half * n[0], c[1] + half * u[1] - half * n[1]];
    var v3 = [c[0] - half * u[0] - half * n[0], c[1] - half * u[1] - half * n[1]];
    var v4 = [c[0] - half * u[0] + half * n[0], c[1] - half * u[1] + half * n[1]];
    var blockFill = [
      ['M', X(v1[0]), Y(v1[1])],
      ['L', X(v2[0]), Y(v2[1])],
      ['L', X(v3[0]), Y(v3[1])],
      ['L', X(v4[0]), Y(v4[1])],
      ['Z']
    ];
    var blockOutline = [];
    var edges = [[v1, v2], [v2, v3], [v3, v4], [v4, v1]];
    for (var e = 0; e < edges.length; e++) {
      blockOutline.push(['M', X(edges[e][0][0]), Y(edges[e][0][1])]);
      blockOutline.push(['L', X(edges[e][1][0]), Y(edges[e][1][1])]);
    }
    var arcPts = [];
    for (var i = 0; i <= 8; i++) {
      var th = -Math.PI / 6 * i / 8;
      var r = 62;
      arcPts.push([A[0] + r * Math.cos(th), A[1] + r * Math.sin(th)]);
    }
    var gEnd = [c[0], c[1] + 115];
    var nEnd = [c[0] + 110 * n[0], c[1] + 110 * n[1]];
    var fEnd = [c[0] + 105 * u[0], c[1] + 105 * u[1]];
    var dark = '#26354a';
    var light = '#e8eef7';
    var scene = {
      schemaVersion: 1,
      sceneId: 'inclined-block-forces',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'incline', commands: lineCmds(A, C) },
        { id: 'ground', commands: lineCmds(A, B) },
        { id: 'side', commands: lineCmds(B, C) },
        { id: 'blockFill', commands: blockFill },
        { id: 'blockOutline', commands: blockOutline },
        { id: 'angleArc', commands: arcSegCmds(arcPts) },
        { id: 'gArrow', commands: arrowCmds(c, gEnd) },
        { id: 'nArrow', commands: arrowCmds(c, nEnd) },
        { id: 'fArrow', commands: arrowCmds(c, fEnd) }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'incline', fill: dark, stroke: { width: 2, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'ground', fill: dark, stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'side', fill: dark, stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'blockFill', fill: light },
          { type: 'path', pathId: 'blockOutline', fill: dark, stroke: { width: 2, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'angleArc', fill: dark, stroke: { width: 1.8, cap: 'round' } },
          { type: 'path', pathId: 'gArrow', fill: dark, stroke: { width: 2.5, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'nArrow', fill: dark, stroke: { width: 2.5, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'fArrow', fill: dark, stroke: { width: 2.5, cap: 'round', join: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: X(c[0] + 12), y: Y(gEnd[1]) }, hAlign: 'left', vAlign: 'middle', color: dark },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: X(nEnd[0] - 10), y: Y(nEnd[1] - 6) }, hAlign: 'right', vAlign: 'bottom', color: dark },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: X(fEnd[0] + 8), y: Y(fEnd[1] - 6) }, hAlign: 'left', vAlign: 'bottom', color: dark },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: X(170), y: Y(305) }, hAlign: 'left', vAlign: 'middle', color: dark }
        ]
      }
    };
    return scene;
  }
};
